/// <summary>
/// Extension of the <c>WhsLicensePlateLabelBuild</c> class for the AAXWarehouseTools model.
/// Renders and attaches captured labels as soon as the label build transaction has committed.
/// </summary>
[ExtensionOf(classStr(WhsLicensePlateLabelBuild))]
final class WhsLicensePlateLabelBuild_AAXWarehouseTools_Extension
{
}

Method.Source:
/// <summary>
/// Extends <c>buildLicensePlateLabels</c> to render pending captured labels once the base
/// implementation, called with <c>next</c>, has completed outside any transaction. Inside an
/// outer transaction the rendering is left to the scheduled batch.
/// </summary>
/// <returns>The label id returned by the base implementation.</returns>
public WHSLabelId buildLicensePlateLabels()
{
    WHSLabelId ret = next buildLicensePlateLabels();

    if (appl.ttsLevel() == 0
        && WHSParameters::find().aaxIsPreviewToWorkAttachmentEnabled())
    {
        AAXWHSLabelCaptureRenderService::renderPendingInline();
    }

    return ret;
}
